const uint16_t* cjkGlyphRows(uint32_t code) {
    if (code > 0xFFFFu) {
        return nullptr;
    }
    const uint16_t key = static_cast<uint16_t>(code);
    std::size_t lo = 0;
    std::size_t hi = 10788;
    while (lo < hi) {
        const std::size_t mid = lo + (hi - lo) / 2;
        if (kCjk[mid].code < key) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    if (lo < 10788 && kCjk[lo].code == key) {
        return kCjk[lo].rows;
    }
    return nullptr;
}

int cjkGlyphCount() { return 10788; }

